SELECT CASE WHEN (s.take_profit - p.entry_price) / p.entry_price * 100 < 0.20 THEN 'a_tp_lt_0.20pct' WHEN (s.take_profit - p.entry_price) / p.entry_price * 100 < 0.40 THEN 'b_0.20-0.40pct' ELSE 'c_ge_0.40pct' END AS tp_bucket, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.realized_pnl < 0) AS losses, ROUND(SUM(p.realized_pnl), 6) AS gross_pnl, ROUND(SUM(p.realized_pnl) - SUM(p.entry_price * p.quantity) * 0.002, 6) AS est_net_pnl_0p2pct FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at IS NOT NULL GROUP BY tp_bucket ORDER BY tp_bucket LIMIT 10